prog = '''"""task-ea26109a: fill background pockets with constant 4.

Rule (verified on both demos and the test):
- Structure color forms walls; background = most common color.
- Any background region that is strictly enclosed (touching no grid border)
  is filled with 4 (demo1 rectangle, demo2 boxes).
- A background region that is a perfect solid rectangle, touches exactly ONE
  grid-border side, and is walled by structure on its other three sides is
  also filled with 4 (test pocket rows5-8 x cols22-24). Non-rectangular
  edge pockets (demo2 top region) and corner slivers with only two structure
  walls (test D/E) are NOT filled.
"""
from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    cnt = {}
    for row in grid:
        for v in row:
            cnt[v] = cnt.get(v, 0) + 1
    bg = max(cnt, key=cnt.get)
    fill = 4
    seen = [[False] * w for _ in range(h)]
    out = [row[:] for row in grid]

    def region_cells(start):
        q = deque([start]); seen[start[0]][start[1]] = True; cells = []
        border_sides = set()
        while q:
            a, b = q.popleft(); cells.append((a, b))
            if a == 0: border_sides.add('top')
            if a == h - 1: border_sides.add('bottom')
            if b == 0: border_sides.add('left')
            if b == w - 1: border_sides.add('right')
            for da, db in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                na, nb = a + da, b + db
                if 0 <= na < h and 0 <= nb < w and not seen[na][nb] and grid[na][nb] == bg:
                    seen[na][nb] = True; q.append((na, nb))
        return cells, border_sides

    def side_walled(cells, side):
        wall = {v for v in cnt if v != bg}
        if side == 'top':
            return all((grid[a - 1][b] in wall) for a, b in cells if a > 0)
        if side == 'bottom':
            return all((grid[a + 1][b] in wall) for a, b in cells if a < h - 1)
        if side == 'left':
            return all((grid[a][b - 1] in wall) for a, b in cells if b > 0)
        return all((grid[a][b + 1] in wall) for a, b in cells if b < w - 1)

    for i in range(h):
        for j in range(w):
            if grid[i][j] == bg and not seen[i][j]:
                cells, sides = region_cells((i, j))
                if not sides:  # strictly enclosed
                    for a, b in cells: out[a][b] = fill
                    continue
                if len(sides) == 1:  # exactly one border side
                    (side,) = tuple(sides)
                    is_rect = len(cells) == (max(a for a, _ in cells) - min(a for a, _ in cells) + 1) * \\
                                       (max(b for _, b in cells) - min(b for _, b in cells) + 1)
                    others = [s for s in ('top', 'bottom', 'left', 'right') if s != side]
                    if is_rect and all(side_walled(cells, s) for s in others):
                        for a, b in cells: out[a][b] = fill
    return out
'''

